def dedup(items):
    seen=set()
    out=[]
    for it in reversed(items):
        if it not in seen:
            seen.add(it); out.append(it)
    return list(reversed(out))

class Inventory:
    def __init__(self): self.items={}
    def add(self,n,q): self.items[n]=self.items.get(n,0)+q
    def restock(self,n,q):
        self.items[n]=self.items.get(n,0)+q  # BUG: no negative guard, creates missing
    def total(self): return sum(self.items.values())

class Bank:
    def __init__(self): self.bal={}
    def open(self,n,a=0): self.bal[n]=a
    def transfer(self,s,d,amt):
        self.bal[s]=self.bal.get(s,0)-amt
        self.bal[d]=self.bal.get(d,0)+amt
        return True

def to_roman(n):
    pairs=[(1000,'M'),(500,'D'),(100,'C'),(50,'L'),(10,'X'),(5,'V'),(1,'I')]
    out=''
    for v,s in pairs:
        out+=s*(n//v); n%=v
    return out

def stable_sort_by(items, keyfn, reverse=False):
    items.sort(key=keyfn, reverse=reverse)  # BUG: mutates input
    return items

